"use client";
// Complete Kashmiri keyboard: every letter, vowel sign and mark found in all our data
// (generated by scripts/build_keyboard.py into lib/ks-keyboard.json), whatever the font.
import { useEffect, useState } from "react";
import data from "@/lib/ks-keyboard.json";

type Key = { c: string; group: "signs" | "letters" | "more"; n: number; name: string; code: string; label: string };
const KEYS = data.keys as Key[];
const GROUPS: [Key["group"], string][] = [["signs", "Vowel signs & marks"], ["letters", "Letters"], ["more", "Numbers & punctuation"]];

// Cursor keys. The text runs right to left, so they move the cursor the way they point on screen:
// ← goes towards the end of the text, → towards its start; ⇤ jumps to the left end, ⇥ to the right end.
export const K_LEFT = "\u2190", K_RIGHT = "\u2192", K_LEFT_END = "\u21E4", K_RIGHT_END = "\u21E5", K_DEL = "\b";

/** Apply one key of the on-screen keyboard to a text box: type, delete, or move the cursor. */
export function applyKey(el: HTMLInputElement | null, text: string, key: string, setText: (v: string) => void) {
  if (!el) return;
  const a = el.selectionStart ?? text.length, b = el.selectionEnd ?? text.length;
  let v = text, pos = a;
  if (key === K_LEFT) pos = Math.min(text.length, (a === b ? a : Math.max(a, b)) + (a === b ? 1 : 0));
  else if (key === K_RIGHT) pos = Math.max(0, (a === b ? a : Math.min(a, b)) - (a === b ? 1 : 0));
  else if (key === K_LEFT_END) pos = text.length;
  else if (key === K_RIGHT_END) pos = 0;
  else if (key === K_DEL) { const f = a === b ? Math.max(0, a - 1) : a; v = text.slice(0, f) + text.slice(b); pos = f; }
  else { v = text.slice(0, a) + key + text.slice(b); pos = a + key.length; }
  if (v !== text) setText(v);
  requestAnimationFrame(() => { el.focus(); el.setSelectionRange(pos, pos); });
}

/** On phones and tablets the text box opens only this keyboard, not the phone's own, unless the person
 *  switches the phone keyboard on (e.g. they have a Kashmiri keyboard installed). Remembered. */
export function usePhoneKeyboard() {
  const [touch, setTouch] = useState(false);
  const [on, setOn] = useState(false);
  useEffect(() => {
    setTouch(window.matchMedia("(pointer: coarse)").matches);
    try { setOn(localStorage.getItem("ks_phone_kb") === "1"); } catch {}
  }, []);
  const toggle = () => setOn((v) => { try { localStorage.setItem("ks_phone_kb", v ? "0" : "1"); } catch {} return !v; });
  return { touch, on, toggle, inputMode: (touch && !on ? "none" : "text") as "none" | "text" };
}

export function Keyboard({ onKey, phone }: { onKey: (s: string) => void; phone?: ReturnType<typeof usePhoneKeyboard> }) {
  const [group, setGroup] = useState<Key["group"]>("signs");
  return (
    <div className="kb" onMouseDown={(e) => e.preventDefault()}>
      <div className="kb-top">
        <div className="tabs" style={{ margin: 0 }}>
          {GROUPS.map(([g, label]) => (
            <button type="button" key={g} aria-pressed={group === g} onClick={() => setGroup(g)}>
              {label} <span className="muted">{KEYS.filter((k) => k.group === g).length}</span>
            </button>
          ))}
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button type="button" className="key wide" onClick={() => onKey(" ")}>space</button>
          <button type="button" className="key wide" onClick={() => onKey(K_DEL)}>⌫ delete</button>
        </div>
      </div>
      <div className="kb-cursor" aria-label="Move the cursor">
        <button type="button" className="key wide" title="To the left end" onClick={() => onKey(K_LEFT_END)}>⇤</button>
        <button type="button" className="key wide arrow" title="One place left" onClick={() => onKey(K_LEFT)}>←</button>
        <button type="button" className="key wide arrow" title="One place right" onClick={() => onKey(K_RIGHT)}>→</button>
        <button type="button" className="key wide" title="To the right end" onClick={() => onKey(K_RIGHT_END)}>⇥</button>
        {phone?.touch && (
          <button type="button" className={`key wide toggle ${phone.on ? "on" : ""}`} onClick={phone.toggle} title="Use the phone's own keyboard too">
            ⌨ Phone keyboard {phone.on ? "on" : "off"}
          </button>
        )}
      </div>
      <div className="kb-grid" dir="rtl">
        {KEYS.filter((k) => k.group === group).map((k) => (
          <button type="button" key={k.c} className={"key" + (k.group === "signs" ? " mark" : "")}
            title={`${k.name} (${k.code})`} aria-label={k.label || k.name} onClick={() => onKey(k.c)}>
            <span className="ks">{k.group === "signs" ? "◌" + k.c : k.c === "‌" ? "|" : k.c}</span>
            {(k.label || k.group === "signs") && <small>{k.label || k.code}</small>}
          </button>
        ))}
      </div>
      <p className="muted small" style={{ margin: "6px 0 0" }}>Point at a key (or hold it on a phone) to see its Unicode name. Signs go after the letter they sit on.</p>
    </div>
  );
}
